e":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2017-06-21T15:00:01Z","viewCount":136423,"durationSeconds":2547,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
