tiquette policy on our channel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/JKEJ9p9YVY8/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2024-11-10T17:00:18Z","viewCount":111325,"durationSeconds":2550,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
