om/dwdocumental We kindly ask viewers to read and stick to the DW netiquette policy on our channel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/BKJ8HlIFVbo/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2024-10-07T18:30:10Z","viewCount":110108,"durationSeconds":2552,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
